import{_ as p,a0 as o,w as r,s as d,ao as l,I as t,x as i,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"七個改變我生活的 Git 小技巧 | LCTT x X-CMD","titleTemplate":false,"description":"七個改變我生活的 Git 小技巧 | LCTT (202106) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"七個改變我生活的 Git 小技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"七個改變我生活的 Git 小技巧 | LCTT (202106) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202106/20201026 7 Git tricks that changed my life","title":"七個改變我生活的 Git 小技巧","tag":"202106","desc":""},"relativePath":"202106/20201026 7 Git tricks that changed my life.md","filePath":"[post].md"}'),g={name:"202106/20201026 7 Git tricks that changed my life.md"};function h(k,s,u,b,c,f){const a=o("Link");return r(),d("div",null,[s[34]||(s[34]=l(`<h1 id="七個改變我生活的-git-小技巧" tabindex="-1">七個改變我生活的 Git 小技巧 <a class="header-anchor" href="#七個改變我生活的-git-小技巧" aria-label="Permalink to “七個改變我生活的 Git 小技巧”">​</a></h1><blockquote><p>這些有用的小技巧將改變你在當前最流行的版本控制系統下的工作方式。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202106/28/110029d64pblurlh5a4a50.jpg" alt=""></p><p>Git 是當前最流行最普遍的版本控制系統之一，它被應用於私有系統和公開網站上各種各樣的開發工作。不論我變得對 Git 有多熟悉，似乎總有些功能等待着被髮掘。下面分享下和 Git 相關的改變我工作方式的一些小技巧。</p><h3 id="_1、git-中的自動糾錯" tabindex="-1">1、Git 中的自動糾錯 <a class="header-anchor" href="#_1、git-中的自動糾錯" aria-label="Permalink to “1、Git 中的自動糾錯”">​</a></h3><p>我們每個人都不時在輸入時犯拼寫錯誤，但是如果你使能了 Git 的自動糾錯功能，你就能讓 Git 自動糾正一些輸入錯誤的子命令。</p><p>假如你想用命令 <code>git status</code> 來檢查狀態，但是你恰巧錯誤地輸入了 <code>git stats</code>。通常情況下，Git 會告訴你 ‘stats’ 不是個有效的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stats</span></span>
<span class="line"><span>git: ‘stats’ is not a git command. See ‘git --help’.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The most similar command is</span></span>
<span class="line"><span>status</span></span></code></pre></div><p>為了避免類似情形，只需要在你的 Git 配置中使能自動糾錯功能。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git config --global help.autocorrect 1</span></span></code></pre></div><p>如果你只想對當前的倉庫生效，就省略掉選項 <code>--global</code>。</p>`,11)),t("p",null,[s[1]||(s[1]=i("這個命令會使能自動糾錯功能。在相應的 ",-1)),e(a,{href:"https://git-scm.com/book/en/v2/Customizing-Git-Git-Configuration#_code_help_autocorrect_code"},{default:n(()=>[...s[0]||(s[0]=[i("Git 官方文檔",-1)])]),_:1}),s[2]||(s[2]=i(" 中可以看到這個命令的詳細説明，但是試着敲一下上面的錯誤命令會使你對這個設置幹了什麼有個直觀的瞭解：",-1))]),s[35]||(s[35]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stats</span></span>
<span class="line"><span>git: ‘stats’ is not a git command. See ‘git --help’.</span></span>
<span class="line"><span>On branch master</span></span>
<span class="line"><span>Your branch is up to date with ‘origin/master’.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nothing to commit, working tree clean</span></span></code></pre></div><p>在上面的例子中，Git 直接運行了它建議命令的第一個，也就是 <code>git status</code>，而不是給你展示它所建議的子命令。</p><h3 id="_2、對提交進行計數" tabindex="-1">2、對提交進行計數 <a class="header-anchor" href="#_2、對提交進行計數" aria-label="Permalink to “2、對提交進行計數”">​</a></h3><p>需要對提交進行計數的原因有很多。例如，一些開發人員利用提交計數來判斷什麼時候遞增工程構建序號，也有一些開發人員用提交計數來對項目進展取得一個整體上的感觀。</p><p>對提交進行計數相當簡單而且直接，下面就是相應的 Git 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git rev-list --count branch-name</span></span></code></pre></div><p>在上述命令中，參數 <code>branch-name</code> 必須是一個你當前倉庫裏的有效分支名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git rev-list –count master</span></span>
<span class="line"><span>32</span></span>
<span class="line"><span>$ git rev-list –count dev</span></span>
<span class="line"><span>34</span></span></code></pre></div><h3 id="_3、倉庫優化" tabindex="-1">3、倉庫優化 <a class="header-anchor" href="#_3、倉庫優化" aria-label="Permalink to “3、倉庫優化”">​</a></h3>`,9)),t("p",null,[s[4]||(s[4]=i("你的代碼倉庫不僅對你來説很寶貴，對你所在的組織也一樣。通過少數幾個慣例你就能使自己的倉庫整潔並且保持最新。",-1)),e(a,{href:"https://opensource.com/article/20/8/dont-ignore-gitignore"},{default:n(()=>[...s[3]||(s[3]=[i("使用 .gitignore 文件",-1)])]),_:1}),s[5]||(s[5]=i(" 就是這些最好的慣例之一。通過使用這個文件你可以告訴 Git 不要保存一些不需要記錄的文件，如二進制文件、臨時文件等等。",-1))]),s[36]||(s[36]=l(`<p>當然，你還可以使用 Git 的垃圾回收來進一步優化你的倉庫。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git gc --prune=now --aggressive</span></span></code></pre></div><p>這個命令在你和你的團隊經常使用 <code>pull</code> 或者 <code>push</code> 操作的時候很有幫助。</p><p>它是一個內部工具，能清理掉你的倉庫裏沒法訪問或者説“空懸”的 Git 對象。</p><h3 id="_4、給未追蹤的文件來個備份" tabindex="-1">4、給未追蹤的文件來個備份 <a class="header-anchor" href="#_4、給未追蹤的文件來個備份" aria-label="Permalink to “4、給未追蹤的文件來個備份”">​</a></h3><p>大多數時候，刪除所有未追蹤的文件是安全的。但很多時候也有這麼一種場景，你想刪掉這些未追蹤的文件同時也想做個備份防止以後需要用到。</p><p>Git 組合一些 Bash 命令和管道操作，可以讓你可以很容易地給那些未追蹤的文件創建 zip 壓縮包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git ls-files --others --exclude-standard -z |\\</span></span>
<span class="line"><span>  xargs -0 tar rvf ~/backup-untracked.zip</span></span></code></pre></div><p>上面的命令就生成了一個名字為 <code>backup-untracked.zip</code> 的壓縮包文件（當然，在 <code>.gitignore</code> 裏面忽略了的文件不會包含在內）。</p><h3 id="_5、瞭解你的-git-文件夾" tabindex="-1">5、瞭解你的 .git 文件夾 <a class="header-anchor" href="#_5、瞭解你的-git-文件夾" aria-label="Permalink to “5、瞭解你的 .git 文件夾”">​</a></h3><p>每個倉庫都有一個 <code>.git</code> 文件夾，它是一個特殊的隱藏文件夾。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -a</span></span>
<span class="line"><span>. … .git</span></span></code></pre></div><p>Git 主要通過兩個東西來工作：</p><ol><li>當前工作樹（你當前檢出的文件狀態）</li><li>你的 Git 倉庫的文件夾（準確地説，包含版本信息的 <code>.git</code> 文件夾的位置）</li></ol><p>這個文件夾存儲了所有參考信息和一些其他的如配置、倉庫數據、HEAD 狀態、日誌等更多諸如此類的重要細節。</p><p>一旦你刪除了這個文件夾，儘管你的源碼沒被刪，但是類似你的工程歷史記錄等遠程信息就沒有了。刪除這個文件夾意味着你的工程（至少本地的複製）不再在版本控制的範疇之內了。這也就意味着你沒法追蹤你的修改；你沒法從遠程倉拉取或推送到遠程倉了。</p><p>通常而言，你需要或者應當對你的 <code>.git</code> 文件夾的操作並不多。它是被 Git 管理的，而且大多數時候是一個禁區。然而，在這個文件夾內還是有一些有趣的工件，比如説當前的 HEAD 狀態在內的就在其中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat .git/HEAD</span></span>
<span class="line"><span>ref: refs/heads/master</span></span></code></pre></div><p>它也隱含着對你倉庫地描述：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat .git/description</span></span></code></pre></div><p>這是一個未命名的倉庫；通過編輯文件 ‘description’ 可以給這個倉庫命名。</p>`,21)),t("p",null,[s[7]||(s[7]=i("Git 鈎子文件夾連同一些鈎子文件例子也在這裏。參考這些例子你就能知道 Git 鈎子能幹什麼了。當然，你也可以 ",-1)),e(a,{href:"https://opensource.com/life/16/8/how-construct-your-own-git-server-part-6"},{default:n(()=>[...s[6]||(s[6]=[i("參考這個 Seth Kenlon 寫的 Git 鈎子介紹",-1)])]),_:1}),s[8]||(s[8]=i("。",-1))]),s[37]||(s[37]=t("h3",{id:"_6、瀏覽另一個分支的文件",tabindex:"-1"},[i("6、瀏覽另一個分支的文件 "),t("a",{class:"header-anchor",href:"#_6、瀏覽另一個分支的文件","aria-label":"Permalink to “6、瀏覽另一個分支的文件”"},"​")],-1)),s[38]||(s[38]=t("p",null,"有時，你會想要瀏覽另一個分支下某個文件的內容。這其實用一個簡單的 Git 命令就可以實現，甚至都不用切換分支。",-1)),t("p",null,[s[10]||(s[10]=i("設想你有一個命名為 ",-1)),e(a,{href:"http://README.md"},{default:n(()=>[...s[9]||(s[9]=[i("README.md",-1)])]),_:1}),s[11]||(s[11]=i(" 的文件，並且它在 ",-1)),s[12]||(s[12]=t("code",null,"main",-1)),s[13]||(s[13]=i(" 分支上。當前你正工作在一個名為 ",-1)),s[14]||(s[14]=t("code",null,"dev",-1)),s[15]||(s[15]=i(" 的分支。",-1))]),s[39]||(s[39]=l(`<p>用下面的 Git 命令，在終端上就行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git show main:README.md</span></span></code></pre></div><p>一旦你執行這個命令，你就能在你的終端上看到 <code>main</code> 分支上該文件的內容。</p><h3 id="_7、git-中的搜索" tabindex="-1">7、Git 中的搜索 <a class="header-anchor" href="#_7、git-中的搜索" aria-label="Permalink to “7、Git 中的搜索”">​</a></h3><p>用一個簡單的命令你就能在 Git 中像專業人士一樣搜索了。更有甚者，儘管你不確定你的修改在哪次提交或者哪個分支上，你依然能搜索。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git rev-list --all | xargs git grep -F &#39;&#39;</span></span></code></pre></div><p>例如，假設你想在你的倉庫中搜索字符串 <code>“font-size: 52 px;&quot;</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git rev-list –all | xargs git grep -F ‘font-size: 52 px;’</span></span>
<span class="line"><span>F3022…9e12:HtmlTemplate/style.css: font-size: 52 px;</span></span>
<span class="line"><span>E9211…8244:RR.Web/Content/style/style.css: font-size: 52 px;</span></span></code></pre></div><h3 id="試試這些小技巧" tabindex="-1">試試這些小技巧 <a class="header-anchor" href="#試試這些小技巧" aria-label="Permalink to “試試這些小技巧”">​</a></h3><p>我希望這些小技巧對你是有用的，或者增加你的生產力或者節省你的大量時間。</p>`,10)),t("p",null,[s[17]||(s[17]=i("你也有一些喜歡的 ",-1)),e(a,{href:"https://acompiler.com/git-tips/"},{default:n(()=>[...s[16]||(s[16]=[i("Git 技巧",-1)])]),_:1}),s[18]||(s[18]=i(" 嗎？在評論區分享吧。",-1))]),s[40]||(s[40]=t("hr",null,null,-1)),t("p",null,[s[20]||(s[20]=i("via: ",-1)),e(a,{href:"https://opensource.com/article/20/10/advanced-git-tips"},{default:n(()=>[...s[19]||(s[19]=[i("https://opensource.com/article/20/10/advanced-git-tips",-1)])]),_:1})]),t("p",null,[s[25]||(s[25]=i("作者：",-1)),e(a,{href:"https://opensource.com/users/acompiler"},{default:n(()=>[...s[21]||(s[21]=[i("Rajeev Bera",-1)])]),_:1}),s[26]||(s[26]=i(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[22]||(s[22]=[i("lujun9972",-1)])]),_:1}),s[27]||(s[27]=i(" 譯者：",-1)),e(a,{href:"https://github.com/BoosterY"},{default:n(()=>[...s[23]||(s[23]=[i("BoosterY",-1)])]),_:1}),s[28]||(s[28]=i(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[24]||(s[24]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[31]||(s[31]=i("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[29]||(s[29]=[i("LCTT",-1)])]),_:1}),s[32]||(s[32]=i(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:n(()=>[...s[30]||(s[30]=[i("Linux中國",-1)])]),_:1}),s[33]||(s[33]=i(" 榮譽推出",-1))])])}const v=p(g,[["render",h]]);export{y as __pageData,v as default};
